const $ = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = value => JSON.parse(JSON.stringify(value));
const paths = {
 grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
 layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',
 shield:'M12 3 8 2v7c0 5 8 9 8 9s8-4 8-9V5z m-3 9 2 2 5-5',
 activity:'M2 12h4l3-8 5 16 3-8h5', code:'m8 6-6 6 6 6 m8-12 6 6-6 6 m-3-15-2 18',
 book:'M3 4h6a4 4 0 0 1 4 3v14a5 5 0 0 0-4-2H3z M13 7a4 4 0 0 1 4-3h4v15h-4a4 4 0 0 0-4 2',
 route:'M5 4a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M19 16a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M7 6h8a4 4 0 0 1 0 8H9a4 4 0 0 0 0 4h8',
 terminal:'M3 4h18v16H3z m4 4 4 4-4 4 m7 0h4', file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',
 plus:'M12 5v14 M5 12h14', chevron:'m9 5 7 7-7 7', down:'m6 9 6 6 6-6',
 arrow:'M4 12h16 m-6-6 6 6-6 6', external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',
 check:'m5 12 4 4L19 6', clock:'M12 8v5l3 2 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',
 search:'M20 20l-5-5 M17 10a7 7 0 1 0-14 0 7 7 0 0 0 14 0',
 alert:'m12 3 10 18H2z M12 9v5 M12 17h.01', refresh:'M20 8V3l-4 4a8 8 0 1 0 3 10 M20 8h-6',
 download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5', stop:'M6 6h12v12H6z',
 copy:'M8 8h13v13H8z M16 8V3H3v13h5', link:'m10 14 4-4 M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',
 edit:'m15 4 5 5-11 11-6 1 1-6z M12 7l5 5', close:'m6 6 12 12 M6 18 18 6',
 settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 4-3 1-1 4H9l-1-4-3-1-2-4 2-5 3-1z',
 info:'M12 11v6 M12 7h.01 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',
 bolt:'m13 2-9 12h7l-1 8 10-13h-7z', branch:'M6 3v12a4 4 0 0 0 4 4h6 M18 5v6a4 4 0 0 1-4 4H6 M6 3h.01 M18 5h.01',
 cloud:'M6 18a5 5 0 0 1-1-10 7 7 0 0 1 13 1 4 4 0 0 1 0 9z', cpu:'M6 6h12v12H6z M9 9h6v6H9z M9 2v4 M15 2v4 M9 18v4 M15 18v4 M2 9h4 M2 15h4 M18 9h4 M18 15h4',
 inbox:'M4 3h16l2 14v4H2v-4z M2 15h6l2 3h4l2-3h6', logout:'M9 4H3v16h6 M9 12h12 m-4-4 4 4-4 4'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.file}"/></svg>`;
const stages = [
 ['literature','文献主张','Literature Reader','book','读取经人工审核的论文主张，保留其 ID、类型与检查规范。','task.manifest.claims','validated claims'],
 ['code','代码检查','Code Inspector','code','盘点仓库文件与 probe 命令，为核查提供受控执行入口。','artifact snapshot','file inventory / probe argv'],
 ['planner','规划调度','Planner','route','在工具预算内选择未检查主张，或输出停止动作。','claims / findings / budget','check(claim_id) | stop'],
 ['experiment','实验执行','Experiment Runner','terminal','按源码摘要、命令和执行环境复用证据，或执行沙箱 probe。','probe argv / sandbox / limits','Evidence + stdout / stderr'],
 ['audit','交叉核查','Cross Auditor','shield','将执行结果与主张规范逐项比较；证据不足保留不确定判定。','Claim + Evidence','Finding + evidence_ids'],
 ['report','生成报告','Reporter','file','归档逐主张结论、运行使用量、停止原因与原始轨迹。','findings / trace / usage','report.md / report.json']
];
const names = {metric_average:'Macro F1 · 指标计算核查',split_leakage:'Data split · 数据划分核查',baseline_budget:'Baseline · 训练预算核查',clean:'Clean artifact · 正常对照'};
const verdictNames = {issue:'发现问题',supported:'证据支持',inconclusive:'证据不足'};
const statusNames = {queued:'等待执行',running:'执行中',completed:'已完成',failed:'执行异常',cancelled:'已停止'};
const navItems = [['workbench','grid','核查任务'],['evidence','shield','证据审查'],['trace','activity','运行轨迹'],['contracts','code','API 契约'],['handoff','branch','训练交接']];
const state = {mode:'demo',page:'workbench',tasks:[],runs:[],run:null,taskId:null,claimId:'C1',filter:'all',query:'',selectedStage:null,endpoint:0,feedback:[],raw:false,poller:null,events:null};
let seed, spec, demoTimer, lastFocus;
const app = $('#app');
function pill(verdict){return `<span class="pill ${verdict==='supported'?'success':verdict==='issue'?'issue':'outline'}">${icon(verdict==='issue'?'alert':verdict==='supported'?'check':'clock')}${esc(verdictNames[verdict]||verdict)}</span>`}
function statusPill(status){return `<span class="pill ${status==='completed'?'success':status}"><span class="dot ${status==='completed'?'':'amber'}"></span>${statusNames[status]||status}</span>`}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3200)}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copy(value){try{await navigator.clipboard.writeText(value);toast('已复制')}catch{modal('复制内容',`<textarea readonly rows="8" style="width:100%">${esc(value)}</textarea>`)}}
async function request(path,body){const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-ArtiCheck-Client':'workbench'},body:body===undefined?undefined:JSON.stringify(body)});const json=await response.json();if(!response.ok)throw new Error(json.error?.message||`HTTP ${response.status}`);return json}
const currentTask = () => state.tasks.find(t=>t.id===(state.run?.task_id||state.taskId))||state.tasks[0];
const currentClaims = () => currentTask()?.manifest.claims||[];
const active = () => state.run && !['completed','failed','cancelled'].includes(state.run.status);
function readFeedback(){try{return JSON.parse(localStorage.getItem('articheck:feedback:v1')||'[]')}catch{return []}}
function saveFeedback(){try{localStorage.setItem('articheck:feedback:v1',JSON.stringify(state.feedback))}catch{}}
function demoTask(sample){return {id:'sample-'+sample.sample_id,title:names[sample.sample_id],paper_id:sample.manifest.paper_id,repo_id:sample.manifest.repo_id,manifest:clone(sample.manifest),trusted_sample:true,sample_id:sample.sample_id,claim_count:sample.manifest.claims.length,created_at:new Date().toISOString()}}
function demoRun(sample){const report=clone(sample.report);report.source_run_id=report.run_id;report.data_source="archived_sample_replay";return {id:'replay-'+sample.sample_id,task_id:'sample-'+sample.sample_id,title:names[sample.sample_id],status:'completed',sandbox:'local',planner:'fixed',budget:{max_tools:8,max_tokens:32000,max_seconds:180,max_usd:1},report_id:sample.report.run_id,report,findings:clone(sample.report.findings),events:sample.events.map((e,i)=>({...clone(e),sequence:i+1})),stages:Object.fromEntries(stages.map(s=>[s[0],'completed'])),feedback:[],created_at:new Date().toISOString()}}
async function init(){
 try{[seed,spec]=await Promise.all([fetch('./demo.json').then(r=>r.json()),fetch('./openapi.json').then(r=>r.json())]);
 try{if(new URLSearchParams(location.search).get('mode')==='demo')throw new Error('Demo selected');const health=await request('/api/health');if(health.service==='articheck'){state.mode='runtime';state.tasks=(await request('/api/tasks')).items;state.runs=(await request('/api/runs')).items;state.feedback=(await request('/api/feedback')).items}}
 catch{}
 if(state.mode==='demo'){state.tasks=seed.samples.map(demoTask);state.runs=seed.samples.map(demoRun);state.feedback=readFeedback()}
 state.taskId=state.tasks[0]?.id;state.page=navItems.some(n=>'#'+n[0]===location.hash)?location.hash.slice(1):'workbench';
 if(state.runs.length){state.run=state.mode==='demo'?state.runs[0]:await request('/api/runs/'+state.runs[0].id);state.taskId=state.run.task_id}
 render();if(active())watchRun();
 }catch(error){app.innerHTML=`<div class="empty">${icon('alert')}<h2>工作台资源载入失败</h2><p>${esc(error.message)}</p><button class="btn" onclick="location.reload()">重新载入</button></div>`}}
function render(){
 const pageName=navItems.find(n=>n[0]===state.page)?.[2]||'核查任务';
 const findings=state.run?.findings||[];const issueCount=findings.filter(f=>f.verdict==='issue').length;
 app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#workbench"><img src="./mark.svg" alt="">ArtiCheck<span>LAB</span></a><div class="workspace-switch"><div class="avatar">AL</div><div class="meta">Artifact Lab<small>个人工作空间</small></div>${icon('down')}</div><nav aria-label="主要导航"><p class="nav-label">WORKSPACE</p>${navItems.map((n,i)=>`${i===3?'<p class="nav-label second">DEVELOPER</p>':''}<button class="nav-item ${state.page===n[0]?'active':''}" data-action="nav" data-page="${n[0]}" ${state.page===n[0]?'aria-current="page"':''}>${icon(n[1])}<span>${n[2]}</span>${n[0]==='evidence'&&issueCount?`<span class="count">${issueCount}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="runtime-panel"><div><span class="dot"></span> ${state.mode==='runtime'?'本地运行时已连接':'样例回放环境'}</div><p>${state.mode==='runtime'?'连接真实 Python 核查流程<br>状态与证据来自本次执行':'基于真实教学样例的归档数据<br>在浏览器中探索完整核查流程'}</p><button data-action="connection">${state.mode==='runtime'?'查看连接信息':'连接本地运行时'} ${icon('arrow')}</button></div><div class="user"><div class="avatar">AC</div><div>研究工作空间<small>ArtiCheck v0.1</small></div><button class="icon-btn" data-action="connection" aria-label="运行环境设置" style="margin-left:auto">${icon('settings')}</button></div></div></aside><div class="content"><header class="topbar"><div class="breadcrumbs">${icon('layers')}<span>Artifact Lab</span>${icon('chevron')}<span>${pageName}</span></div><div class="top-actions"><span class="flex"><span class="dot"></span> ${state.mode==='runtime'?'Runtime connected':'Sample replay'}</span><span class="mono">API v1</span><button class="icon-btn" data-action="help" aria-label="使用帮助">${icon('info')}</button></div></header><main id="main" class="page fade"><div class="page-title between"><div><div class="eyebrow">${state.page==='contracts'?'DEVELOPER EXPERIENCE':state.page==='handoff'?'HUMAN IN THE LOOP':'ARTIFACT REVIEW WORKSPACE'}</div><h1>${pageName==='核查任务'?'核查工作台':pageName}</h1><p class="subtitle">${pageSubtitle()}</p></div><div class="title-actions">${state.page==='contracts'?`<button class="btn" data-action="download-spec">${icon('download')}导出 OpenAPI</button>`:`<button class="btn" data-action="export" ${!state.run?.report?'disabled':''}>${icon('download')}导出报告</button><button class="btn primary" data-action="new">${icon('plus')}新建核查</button>`}</div></div>${renderPage()}<footer class="page-footer"><span class="flex">${icon('shield')}每条结论，关联原始执行证据。</span><span>${state.mode==='runtime'?'LOCAL RUNTIME':'ARCHIVED SAMPLE REPLAY'} <span style="margin:0 6px;color:#c8d1cd">/</span> ArtiCheck Workbench</span></footer></main></div></div>`;
 bindInputs();
}
function pageSubtitle(){return {workbench:'从实验主张到执行证据，让论文复现的每一步都清晰可见。',evidence:'逐条核对实验主张、执行结果与证据，保留每一次人工审查。',trace:'沿着规划、工具调用与交叉核查，追溯每条结论的来源。',contracts:'用界面反推接口：请求、状态、事件与证据使用同一份契约。',handoff:'让人工修正进入可审计的数据队列，连接核查与后训练。'}[state.page]}
function renderPage(){if(state.page==='contracts')return contractsView();if(state.page==='handoff')return handoffView();if(state.page==='trace')return traceView();if(state.page==='evidence')return `<div class="view-tabs">${runSelector()}</div><div class="work-grid" style="margin-top:0">${claimsCard()}${evidenceCard()}</div>`;return workbenchView()}
function runSelector(){return `<div class="run-heading"><select id="run-select" aria-label="选择核查运行">${state.runs.length?state.runs.map(r=>`<option value="${esc(r.id)}" ${r.id===state.run?.id?'selected':''}>${esc(r.title)} · ${statusNames[r.status]}</option>`).join(''):'<option value="">尚无运行记录</option>'}</select></div>`}
function workbenchView(){
 const run=state.run,findings=run?.findings||[],report=run?.report,task=currentTask();
 const issues=findings.filter(f=>f.verdict==='issue').length,reviewed=new Set((run?.feedback||state.feedback.filter(f=>f.run_id===report?.run_id)).map(f=>f.claim_id));
 const pending=findings.filter(f=>f.verdict==='issue'&&!reviewed.has(f.claim_id)).length;
 return `<div class="metrics">${metric('实验主张',task?.claim_count||0,'条','book',`${findings.length} 条已完成核查`)}${metric('检出问题',issues,'项','alert','指标 · 数据 · 基线')}${metric('待人工复核',pending,'项','shield',pending?'为关键结论补充审查':'审查队列已更新')}${metric('工具调用',report?.usage.tools||0,`/ ${run?.budget.max_tools??8}`,'terminal',`预算 ${run?.budget.max_seconds??180}s · 固定策略`)}</div><section class="card"><div class="card-head between"><div><div class="kicker">CURRENT REVIEW</div>${runSelector()}<div class="run-meta"><span class="flex">${icon('code')}<span class="mono">${esc(task?.repo_id||'选择一个任务')}</span></span><span class="pill outline">Fixed Planner</span><span class="pill outline">${esc(run?.sandbox||'Docker')} sandbox</span>${run?.id?`<span class="mono">${esc(run.id.slice(0,14))}</span>`:''}</div></div><div class="stack" style="align-items:flex-end;gap:9px">${run?statusPill(run.status):'<span class="pill outline">就绪</span>'}${active()?`<button class="btn small danger" data-action="cancel">${icon('stop')}停止</button>`:`<button class="btn small" data-action="rerun">${icon('refresh')}${run?'重新核查':'运行样例'}</button>`}</div></div><div class="pipeline-wrap"><div class="pipeline">${stages.map(s=>`<button class="stage ${run?.stages?.[s[0]]||'pending'} ${state.selectedStage===s[0]?'selected':''}" data-action="stage" data-id="${s[0]}" aria-label="查看 ${s[1]} 角色"><span class="stage-icon">${icon(s[3])}</span><span class="name">${s[1]}</span><span class="english">${s[2]}</span></button>`).join('')}</div><div class="pipeline-foot"><span>${icon('clock')}${report?`${state.mode==='demo'?'原始样例执行':'本次执行'} ${(report.elapsed_seconds).toFixed(2)}s`:'从主张清单开始，按需获取执行证据'}</span><span>${icon('link')}Evidence-linked workflow<span class="pill outline">6 roles</span></span></div></div></section>${run?.error?`<div class="error-box">${esc(run.error)}</div>`:''}<div class="work-grid">${claimsCard()}${state.selectedStage?stageCard():evidenceCard()}</div>${timelineCard()}`;
}
function metric(label,value,suffix,i,foot){return `<section class="metric"><div class="label">${label}</div><div class="metric-icon">${icon(i)}</div><div class="value">${value}<span>${suffix}</span></div><div class="foot">${foot}</div></section>`}
function translated(claim){return {metric:'报告指标与实验结果一致',split_disjoint:'训练集与测试集无样本重叠',baseline_equal:'方法与基线使用相同训练预算'}[claim?.kind]||claim?.text||'选择一条实验主张'}
function claimDescription(claim,finding){if(!finding)return '等待对应 probe 的执行证据';if(claim.kind==='metric'){return `预期 ${claim.spec.expected.toFixed(6)} · 容差 ${claim.spec.tolerance}`}if(claim.kind==='split_disjoint')return '比较训练集与测试集的样本 ID 集合';return '比较方法与 baseline 的实际训练步数'}
function claimsCard(){const claims=currentClaims(),findings=state.run?.findings||[];return `<section class="card"><div class="card-head between"><h2 class="section-title">实验主张 <span class="tiny">${claims.length} CLAIMS</span></h2><span class="muted" style="font-size:10px">点击查看证据 ${icon('arrow')}</span></div><div class="table-tools"><div class="tabs">${[['all','全部',claims.length],['issue','问题',findings.filter(f=>f.verdict==='issue').length],['supported','支持',findings.filter(f=>f.verdict==='supported').length]].map(t=>`<button class="tab ${state.filter===t[0]?'active':''}" data-action="filter" data-value="${t[0]}">${t[1]}<small>${t[2]}</small></button>`).join('')}</div><label class="search">${icon('search')}<input id="claim-search" aria-label="搜索主张" placeholder="搜索主张" value="${esc(state.query)}"></label></div><div id="claim-list">${claimRows()}</div></section>`}
function claimRows(){const claims=currentClaims(),findings=state.run?.findings||[];const visible=claims.filter(c=>{const finding=findings.find(f=>f.claim_id===c.id);return (state.filter==='all'||finding?.verdict===state.filter)&&(!state.query||`${c.id} ${c.text} ${translated(c)}`.toLowerCase().includes(state.query.toLowerCase()))});return visible.length?visible.map(c=>{const f=findings.find(f=>f.claim_id===c.id);const hasFeedback=state.feedback.some(r=>r.run_id===state.run?.report_id&&r.claim_id===c.id);return `<div class="claim ${state.claimId===c.id?'selected':''}" data-action="claim" data-id="${esc(c.id)}" role="button" tabindex="0"><div class="claim-top"><div><span class="id mono">${esc(c.id)}</span><span class="name">${esc(translated(c))}</span></div>${f?pill(f.verdict):'<span class="pill outline">待检查</span>'}</div><p>${esc(claimDescription(c,f))}</p><div class="claim-footer"><span class="flex">${icon('link')}${f?.evidence_ids.length||0} 条执行证据</span><span>${hasFeedback?'已人工审查':c.kind==='metric'?'METRIC CHECK':c.kind==='split_disjoint'?'DATA INTEGRITY':'BASELINE FAIRNESS'}</span></div></div>`}).join(''):`<div class="empty">${icon('search')}<p>没有匹配的主张</p></div>`}
function evidenceCard(){const claim=currentClaims().find(c=>c.id===state.claimId)||currentClaims()[0];const f=state.run?.findings.find(f=>f.claim_id===claim?.id);const evidence=state.run?.report?.evidence?.find(e=>f?.evidence_ids.includes(e.id))||state.run?.events?.find(e=>e.kind==='tool')?.evidence;const payload=evidence?.payload?.payload||{};if(!f)return `<section class="card evidence-card"><div class="card-head"><h2>证据详情</h2></div><div class="empty">${icon('file')}<p>执行核查后，在这里查看<br>主张、实际输出与判定之间的关系。</p><button class="btn primary" data-action="rerun">${icon('bolt')}开始核查</button></div></section>`;
 let comparison='';if(claim.kind==='metric'){comparison=`<div><div class="key">论文预期值</div><div class="number">${Number(claim.spec.expected).toFixed(6)}</div></div><div><div class="key">实际观测值</div><div class="number ${f.verdict==='issue'?'issue':''}">${payload[claim.spec.key]===undefined?'—':Number(payload[claim.spec.key]).toFixed(6)}</div></div>`}else if(claim.kind==='split_disjoint'){const train=payload[claim.spec.train_key]||[],test=payload[claim.spec.test_key]||[];comparison=`<div><div class="key">样本 ID 交集</div><div class="number ${f.verdict==='issue'?'issue':''}">${train.filter(id=>test.includes(id)).length} <small>个</small></div></div><div><div class="key">核查的样本 ID</div><div class="number">${train.length} / ${test.length}</div></div>`}else{comparison=`<div><div class="key">方法训练步数</div><div class="number">${esc(payload[claim.spec.method_key]??'—')}</div></div><div><div class="key">基线训练步数</div><div class="number ${f.verdict==='issue'?'issue':''}">${esc(payload[claim.spec.baseline_key]??'—')}</div></div>`}
 const feedback=state.feedback.filter(r=>r.run_id===state.run.report_id&&r.claim_id===claim.id);
 return `<section class="card evidence-card"><div class="card-head between"><h2 class="section-title">证据详情 <span class="tiny mono">${esc(claim.id)}</span></h2><button class="icon-btn" data-action="raw" aria-label="切换原始证据">${icon('external')}</button></div><div class="evidence"><div class="between">${pill(f.verdict)}<span class="mono muted" style="font-size:9px">${esc(claim.kind)}</span></div><h3 class="evidence-title">${esc(f.verdict==='issue'?{metric:'指标结果与报告值不一致',split_disjoint:'训练与测试样本存在交集',baseline_equal:'方法与基线的训练预算不一致'}[claim.kind]:f.verdict==='supported'?'当前执行证据支持这条主张':'还需要更多执行证据')}</h3><p class="desc">${esc(claim.text)}</p><div class="comparison">${comparison}</div><div class="evidence-label">${icon('terminal')}执行命令</div><div class="command"><span><span class="prompt">$</span><code>${esc((claim.probe||currentTask().manifest.probe).join(' '))}</code></span><button class="icon-btn" data-action="copy-command" aria-label="复制执行命令">${icon('copy')}</button></div><div class="evidence-label">${icon('link')}证据指纹 · SHA-256</div><div class="evidence-id"><code>${esc((evidence?.id||'—').slice(0,28))}${evidence?'…':''}</code><button class="icon-btn" data-action="copy-evidence" aria-label="复制证据 ID">${icon('copy')}</button></div>${state.raw?`<pre class="raw-json">${esc(JSON.stringify(evidence?.payload||f,null,2))}</pre>`:''}${feedback.length?`<div class="info-strip" style="margin-top:15px;font-size:10px">${icon('check')}已由 ${esc(feedback.at(-1).reviewer)} 审查 · ${esc(feedback.at(-1).reason)}</div>`:''}<div class="evidence-actions"><button class="btn" data-action="raw">${icon('code')}原始证据</button><button class="btn primary" data-action="feedback" ${!state.run?.report?'disabled':''}>${icon('edit')}人工复核</button></div><p class="evidence-note">${icon('info')}判定对应当前 probe 与主张规范。人工修正保留原始证据与历史结论。</p></div></section>`;
}
function stageCard(){const s=stages.find(s=>s[0]===state.selectedStage);return `<section class="card"><div class="card-head between"><h2>角色接口</h2><button class="icon-btn" data-action="close-stage" aria-label="关闭角色详情">${icon('close')}</button></div><div class="stage-detail"><span class="pill success">${icon(s[3])}${esc(s[1])}</span><h3 class="role-name">${s[2]}</h3><p>${s[4]}</p><div class="kv"><span>输入</span><span class="mono">${esc(s[5])}</span></div><div class="kv"><span>输出</span><span class="mono">${esc(s[6])}</span></div><div class="kv"><span>当前状态</span><span>${esc(state.run?.stages[s[0]]||'pending')}</span></div><button class="btn" data-action="nav" data-page="contracts" style="margin-top:10px">查看 API 契约 ${icon('arrow')}</button></div></section>`}
const eventLabels={preflight:['输入与仓库检查完成','主张清单已读取，probe 执行入口已确认'],decision:['Planner 输出动作','按当前证据与预算选择检查项'],tool:['实验工具返回结果','执行输出已关联到内容指纹'],audit:['完成主张交叉核查','生成判定并记录证据引用'],complete:['核查报告已归档','报告、使用量与停止原因已保存'],model:['模型采样返回','保留采样元数据与策略版本']};
function eventText(event){if(event.kind==='decision')return event.action.action==='stop'?'Planner 输出 stop，结束核查':`Planner 选择 ${event.action.claim_id}，执行 check`;if(event.kind==='audit')return `${event.finding.claim_id} · ${verdictNames[event.finding.verdict]}`;if(event.kind==='tool')return event.evidence.success?'probe 执行成功，已记录 stdout 与证据指纹':'probe 未产生有效结果，保留错误记录';return eventLabels[event.kind]?.[1]||event.kind}
function timelineCard(){const events=state.run?.events||[];return `<section class="card timeline-card"><div class="card-head between"><h2 class="section-title">执行动态 <span class="tiny">${events.length} EVENTS</span></h2><button class="icon-btn" data-action="nav" data-page="trace" aria-label="查看全部轨迹">${icon('arrow')}</button></div><div class="timeline">${events.length?events.slice(-4).map(e=>`<div class="event"><span class="event-dot"></span><span class="event-text"><b>${esc(eventText(e))}</b><span class="trace-tag mono">${esc(e.kind)}</span></span><time>#${String(e.sequence).padStart(3,'0')}</time></div>`).join(''):'<div class="empty" style="padding:22px">启动核查后，规划动作和执行事件会显示在这里。</div>'}</div></section>`}
function traceView(){const events=state.run?.events||[];return `<div class="between" style="margin-bottom:20px">${runSelector()}<button class="btn" data-action="export-trace" ${!events.length?'disabled':''}>${icon('download')}导出 JSONL</button></div><div class="info-strip" style="margin-bottom:20px">${icon('info')}当前策略为 FixedPlanner。没有模型调用的运行不包含生成 token 或行为 log-prob。</div><section class="card"><div class="card-head between"><h2>运行事件</h2><span class="pill outline">${events.length} EVENTS</span></div><div class="scroll-table"><table class="full-table"><thead><tr><th>序号</th><th>事件类型</th><th>执行内容</th><th>原始记录</th></tr></thead><tbody>${events.map(e=>`<tr><td class="mono">${String(e.sequence).padStart(3,'0')}</td><td><span class="pill outline mono">${esc(e.kind)}</span></td><td>${esc(eventText(e))}</td><td><button class="icon-btn" data-action="event" data-index="${e.sequence-1}" aria-label="查看事件 ${e.sequence}">${icon('code')}</button></td></tr>`).join('')}</tbody></table>${!events.length?'<div class="empty">暂无执行轨迹</div>':''}</div></section>`}
function endpoints(){return Object.entries(spec.paths).flatMap(([path,operations])=>Object.entries(operations).map(([method,operation])=>({path,method,...operation})))}
function contractsView(){const all=endpoints(),entry=all[state.endpoint]||all[0];return `<div class="contract-grid"><section class="card"><div class="card-head between"><h2>接口目录</h2><span class="pill outline">${all.length} endpoints</span></div>${all.map((e,i)=>`<button class="endpoint ${state.endpoint===i?'active':''}" data-action="endpoint" data-index="${i}"><span class="method ${e.method}">${e.method.toUpperCase()}</span><span class="path">${esc(e.path)}</span></button>`).join('')}</section><section class="card"><div class="card-head between"><h2>${esc(entry.summary)}</h2><span class="pill success">本地运行时已实现</span></div><div class="contract-body"><div class="flex"><span class="method ${entry.method}">${entry.method.toUpperCase()}</span><code>${esc(entry.path)}</code></div><p>${esc(entry.description)}</p><div class="contract-meta" style="margin-top:16px"><span>Transport · ${entry.path.endsWith('/events')?'SSE':'JSON / HTTP'}</span><span>Runtime · localhost:8787</span></div>${entry['x-ui-request']!==null?`<div class="evidence-label">Request body</div><pre class="contract-code">${esc(JSON.stringify(entry['x-ui-request'],null,2))}</pre>`:''}<div class="evidence-label">${entry.path.endsWith('/events')?'Event payload':'Response example'}</div><pre class="contract-code">${esc(JSON.stringify(entry['x-ui-response'],null,2))}</pre><div class="info-strip">${icon('link')}界面中的任务、运行与证据 ID 对应这些资源。异步运行的 id 与最终 pipeline report_id 分开保存。</div><div class="flex" style="margin-top:20px"><button class="btn" data-action="copy-curl">${icon('copy')}复制 cURL</button><button class="btn" data-action="download-spec">${icon('download')}OpenAPI JSON</button></div></div></section></div>`}
function handoffView(){return `<div class="info-strip">${icon('branch')}人工修正先进入审核队列，保留 reviewer、理由与原始 verdict；不直接修改既有报告或触发训练。</div><div class="handoff-flow">${[['01','人工复核','确认误报、漏报与证据不足'],['02','反馈归档','关联原始 run_id 与 claim_id'],['03','样本审核','核对冲突标注与仓库隔离'],['04','训练交接','审核后准备 SFT 或 RL 数据']].map(x=>`<div><small>${x[0]}</small><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div><section class="card"><div class="card-head between"><h2 class="section-title">人工反馈 <span class="tiny">${state.feedback.length} RECORDS</span></h2><button class="btn small" data-action="export-feedback" ${!state.feedback.length?'disabled':''}>${icon('download')}导出 JSONL</button></div><div class="scroll-table"><table class="full-table"><thead><tr><th>主张 / 运行</th><th>人工标签</th><th>审查理由</th><th>审核人</th><th>样本标记</th></tr></thead><tbody>${state.feedback.map(f=>`<tr><td><b>${esc(f.claim_id)}</b><small class="muted mono" style="display:block;margin-top:5px">${esc(f.run_id.slice(0,12))}</small></td><td>${pill(f.label?'issue':'supported')}</td><td>${esc(f.reason)}</td><td>${esc(f.reviewer)}</td><td><span class="pill ${f.hard_sample?'issue':'success'}">${f.hard_sample?'困难样本候选':'人工确认'}</span></td></tr>`).join('')}</tbody></table>${!state.feedback.length?'<div class="empty">先在「证据审查」中复核一条主张，反馈记录会出现在这里。</div>':''}</div></section>`}
function bindInputs(){const selector=$('#run-select');if(selector)selector.addEventListener('change',()=>selectRun(selector.value));const search=$('#claim-search');if(search)search.addEventListener('input',()=>{state.query=search.value;$('#claim-list').innerHTML=claimRows()})}
async function selectRun(id){if(!id)return;stopWatching();state.run=state.mode==='runtime'?await request('/api/runs/'+id):state.runs.find(r=>r.id===id);state.taskId=state.run.task_id;state.selectedStage=null;state.claimId=currentClaims()[0]?.id;state.filter='all';state.raw=false;render();if(active())watchRun()}
function stopWatching(){clearInterval(state.poller);state.events?.close();state.events=null}
function watchRun(){stopWatching();const id=state.run.id;state.poller=setInterval(async()=>{if(state.mode==='runtime'){try{state.run=await request('/api/runs/'+id);state.runs=(await request('/api/runs')).items;state.feedback=(await request('/api/feedback')).items;render();if(!active())stopWatching()}catch(error){stopWatching();toast(error.message)}}},700)}
async function startRun(taskId,options={}){
 if(active()||(state.mode==='demo'&&state.runs.some(r=>r.status==='running')))return toast('请先停止当前运行，或等待核查结束');
 const body={task_id:taskId,sandbox:options.sandbox||'local',planner:'fixed',budget:options.budget||{max_tools:8,max_tokens:32000,max_seconds:180,max_usd:1}};
 try{if(state.mode==='runtime'){const row=await request('/api/runs',body);state.run=await request('/api/runs/'+row.id);state.runs=(await request('/api/runs')).items;state.taskId=taskId;state.page='workbench';state.claimId=currentClaims()[0]?.id;render();watchRun();toast('已提交到本地 Python 运行时')}
 else startReplay(taskId,body);
 }catch(error){toast(error.message)}
}
function auditReplay(claim,evidence){const p=evidence?.payload?.payload;let issue=false,reason='';if(!p)return {claim_id:claim.id,verdict:'inconclusive',score:0,reason:'No execution evidence',evidence_ids:[]};try{const s=claim.spec;if(claim.kind==='metric'){if(!Number.isFinite(p[s.key])||!Number.isFinite(s.expected))throw Error();issue=Math.abs(p[s.key]-s.expected)>s.tolerance;reason=`Observed ${p[s.key]}; expected ${s.expected} ± ${s.tolerance}`}else if(claim.kind==='split_disjoint'){if(!Array.isArray(p[s.train_key])||!Array.isArray(p[s.test_key]))throw Error();const overlap=p[s.train_key].filter(x=>p[s.test_key].includes(x));issue=overlap.length>0;reason=`Train/test overlap: ${overlap.length} IDs`}else{if(!Number.isFinite(p[s.method_key])||!Number.isFinite(p[s.baseline_key]))throw Error();issue=p[s.method_key]!==p[s.baseline_key];reason=`Method steps=${p[s.method_key]}; baseline steps=${p[s.baseline_key]}`}}catch{return {claim_id:claim.id,verdict:'inconclusive',score:0,reason:'Missing/invalid archived evidence',evidence_ids:[evidence.id]}}return {claim_id:claim.id,verdict:issue?'issue':'supported',score:issue?1:0,reason:reason+'; archived sample evidence',evidence_ids:[evidence.id]}}
function startReplay(taskId,body){const task=state.tasks.find(t=>t.id===taskId),sample=seed.samples.find(s=>s.sample_id===task.sample_id);if(!sample)return toast('该样例不可用');const run=demoRun(sample);run.id='replay-'+crypto.randomUUID();run.task_id=taskId;run.title=task.title;run.budget=body.budget;run.status='running';run.report=null;run.findings=[];run.events=[];run.stages=Object.fromEntries(stages.map(s=>[s[0],'pending']));state.run=run;state.runs.unshift(run);state.taskId=taskId;state.page='workbench';state.claimId=task.manifest.claims[0]?.id;state.selectedStage=null;const report=clone(sample.report);report.source_run_id=report.run_id;report.run_id=run.id;report.data_source='archived_sample_replay';report.findings=task.manifest.claims.map(c=>auditReplay(c,report.evidence[0]));const full=[{kind:'preflight',data:{}},{kind:'decision',action:{action:'check',claim_id:task.manifest.claims[0].id}},{kind:'tool',evidence:report.evidence[0]},...report.findings.map(f=>({kind:'audit',finding:f})),{kind:'complete',report}];let index=0;render();toast('开始回放教学样例的归档证据');clearInterval(demoTimer);demoTimer=setInterval(()=>{if(run.status!=='running'){clearInterval(demoTimer);return}const event={...full[index],sequence:index+1};run.events.push(event);if(event.kind==='preflight'){run.stages.literature='completed';run.stages.code='completed';run.stages.planner='running'}if(event.kind==='tool'){run.stages.experiment='completed';run.stages.audit='running'}if(event.kind==='audit')run.findings.push(event.finding);if(event.kind==='complete'){run.status='completed';run.report=report;run.report_id=report.run_id;run.stages=Object.fromEntries(stages.map(s=>[s[0],'completed']));clearInterval(demoTimer);toast('样例回放完成')}index++;if(state.run?.id===run.id)render()},650)}
function modal(title,body,footer='',wide=false){lastFocus=document.activeElement;$('#dialog-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;const first=$('button,input,select,textarea',$('#dialog-root'));first?.focus()}
function closeModal(){$('#dialog-root').innerHTML='';lastFocus?.focus()}
function showNew(){const selected=currentTask()||state.tasks[0];modal('新建核查任务',`<form id="new-form"><div id="form-error"></div><div class="form-grid"><div class="field"><label for="task-name">任务名称</label><input id="task-name" name="title" value="${esc(selected?.title||'新的 Artifact 核查')}" required maxlength="200"></div><div class="field"><label for="sample-select">任务来源</label><select id="sample-select" name="sample_id">${seed.samples.map(s=>`<option value="${s.sample_id}" ${s.sample_id===selected?.sample_id?'selected':''}>${names[s.sample_id]}</option>`).join('')}${state.mode==='runtime'?'<option value="custom">导入工作区 task.json</option>':''}</select></div></div><div class="field hidden" id="path-field"><label for="task-path">任务文件路径</label><input id="task-path" name="task_path" placeholder="examples/task.json"><small>相对本地服务启动时指定的 workspace。外部 artifact 仅使用 Docker。</small></div><div class="field" id="claim-edit-field"><label>审核主张 <span class="muted" style="font-weight:400">· 可修改指标预期值</span></label><div id="claim-edits"></div><small>主张规范随任务保存；sample 的 probe 命令保持只读。</small></div><div class="form-grid"><div class="field"><label for="sandbox">执行环境</label><select id="sandbox" name="sandbox"><option value="local">Trusted local · 内置样例</option><option value="docker">Docker · 隔离执行</option></select></div><div class="field"><label for="max-tools">工具调用预算</label><input id="max-tools" name="max_tools" type="number" min="0" max="50" value="8" required></div></div><div class="form-grid"><div class="field"><label for="max-seconds">时间预算（秒）</label><input id="max-seconds" name="max_seconds" type="number" min="1" max="600" value="180" required></div><div class="field"><label for="max-tokens">模型 token 预算</label><input id="max-tokens" name="max_tokens" type="number" min="0" max="200000" value="32000" required></div></div><div class="info-strip">${icon(state.mode==='runtime'?'terminal':'activity')}${state.mode==='runtime'?'提交后调用真实 Python 核查流程。当前 API 支持固定 Planner。':'当前为样例回放：使用归档 probe 输出演示核查交互。'}</div></form>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="submit-task">${icon('bolt')}${state.mode==='runtime'?'创建并运行':'创建并回放'}</button>`,true);$('#sample-select').addEventListener('change',updateClaimEdits);updateClaimEdits()}
function updateClaimEdits(){const sampleId=$('#sample-select').value,custom=sampleId==='custom';$('#path-field').classList.toggle('hidden',!custom);$('#claim-edit-field').classList.toggle('hidden',custom);$('#sandbox').value=custom?'docker':'local';$('#sandbox').disabled=custom;if(!custom){const sample=seed.samples.find(s=>s.sample_id===sampleId);$('#claim-edits').innerHTML=sample.manifest.claims.map(c=>`<div class="claim-edit"><span class="mono">${c.id}</span><span>${translated(c)}</span>${c.kind==='metric'?`<input name="expected-${c.id}" aria-label="${c.id} 指标预期值" value="${c.spec.expected}" type="number" step="any" required>`:'<span class="pill outline">固定规则</span>'}</div>`).join('')}}
async function submitTask(){const form=$('#new-form');if(!form.reportValidity())return;const data=new FormData(form),sampleId=data.get('sample_id');const body={title:data.get('title')};if(sampleId==='custom'){body.task_path=data.get('task_path');if(!body.task_path)return $('#form-error').innerHTML='<p class="form-error">请填写 task.json 路径</p>'}else{body.sample_id=sampleId;body.claims=clone(seed.samples.find(s=>s.sample_id===sampleId).manifest.claims);for(const claim of body.claims)if(claim.kind==='metric')claim.spec.expected=Number(data.get('expected-'+claim.id))}try{let task;if(state.mode==='runtime')task=await request('/api/tasks',body);else{task={...demoTask(seed.samples.find(s=>s.sample_id===sampleId)),id:'task-'+crypto.randomUUID(),title:body.title};task.manifest.claims=body.claims;task.claim_count=body.claims.length}state.tasks.push(task);const options={sandbox:sampleId==='custom'?'docker':data.get('sandbox'),budget:{max_tools:Number(data.get('max_tools')),max_tokens:Number(data.get('max_tokens')),max_seconds:Number(data.get('max_seconds')),max_usd:1}};closeModal();await startRun(task.id,options)}catch(error){$('#form-error').innerHTML=`<p class="form-error">${esc(error.message)}</p>`}}
function showFeedback(){const claim=currentClaims().find(c=>c.id===state.claimId)||currentClaims()[0];const finding=state.run?.findings.find(f=>f.claim_id===claim.id);modal('人工复核 · '+claim.id,`<form id="feedback-form"><div id="form-error"></div><div class="info-strip" style="margin-bottom:20px">${icon('shield')}${esc(translated(claim))} · 当前判定：${verdictNames[finding.verdict]}</div><div class="form-grid"><div class="field"><label for="feedback-label">人工判定</label><select id="feedback-label" name="label"><option value="1" ${finding.verdict==='issue'?'selected':''}>存在问题</option><option value="0" ${finding.verdict!=='issue'?'selected':''}>主张成立 / 无此问题</option></select></div><div class="field"><label for="reviewer">审核人</label><input id="reviewer" name="reviewer" placeholder="reviewer-01" required maxlength="100"></div></div><div class="field"><label for="feedback-reason">复核依据</label><textarea id="feedback-reason" name="reason" placeholder="补充独立重算结果、证据位置或修正理由…" required maxlength="2000"></textarea></div><p class="field-hint">此记录关联原始 run_id 与 claim_id，不覆盖原始报告。</p></form>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="submit-feedback">${icon('check')}保存复核记录</button>`)}
async function submitFeedback(){const form=$('#feedback-form');if(!form.reportValidity())return;const data=new FormData(form),claim=currentClaims().find(c=>c.id===state.claimId)||currentClaims()[0];const body={claim_id:claim.id,label:Number(data.get('label')),reviewer:String(data.get('reviewer')).trim(),reason:String(data.get('reason')).trim()};if(!body.reviewer||!body.reason)return;try{let row;if(state.mode==='runtime')row=await request('/api/runs/'+state.run.id+'/feedback',body);else{const finding=state.run.findings.find(f=>f.claim_id===claim.id);row={...body,run_id:state.run.report_id,paper_id:state.run.report.paper_id,repo_id:state.run.report.repo_id,source:'human',timestamp:new Date().toISOString(),previous_verdict:finding.verdict,hard_sample:(finding.verdict==='issue')!==Boolean(body.label)||finding.verdict==='inconclusive'}}state.feedback.push(row);state.run.feedback=state.feedback.filter(f=>f.run_id===state.run.report_id);if(state.mode==='demo')saveFeedback();closeModal();render();toast('复核已归档，可在「训练交接」中查看')}catch(error){$('#form-error').innerHTML=`<p class="form-error">${esc(error.message)}</p>`}}
function connection(){modal('运行环境',`<div class="connection-option"><h3>${icon('activity')}浏览器样例回放 ${state.mode==='demo'?'<span class="pill success">当前</span>':''}</h3><p>使用四组内置教学 artifact 的归档执行输出。支持任务配置、角色查看、证据审查、反馈与数据导出。</p></div><div class="connection-option"><h3>${icon('terminal')}连接本地 Python 运行时 ${state.mode==='runtime'?'<span class="pill success">当前</span>':''}</h3><p>在 ArtiCheck 仓库根目录启动服务，然后打开本地地址。界面和 API 同源，真实执行与数据保存在本机。</p><pre>python -m articheck.workbench --port 8787</pre><a class="btn small" href="http://127.0.0.1:8787" target="_blank" rel="noopener">打开本地工作台 ${icon('external')}</a></div><p class="field-hint">托管预览与本地运行时互相独立。真实核查使用本地服务；网页不跨域访问你的文件系统。</p>`)}
function showExport(){modal('导出核查报告',`<div class="connection-option"><h3>${icon('file')}结构化报告 · JSON</h3><p>包含 Findings、Evidence、使用量和停止原因，适合后续程序处理。</p><button class="btn" data-action="export-json">${icon('download')}下载 JSON</button></div><div class="connection-option"><h3>${icon('book')}审查报告 · Markdown</h3><p>包含逐主张判定与证据引用，便于人工复核和分享。</p><button class="btn" data-action="export-md">${icon('download')}下载 Markdown</button></div>`)}
async function exportReport(format){if(!state.run?.report)return;try{if(state.mode==='runtime'){const r=await fetch(`/api/runs/${state.run.id}/report?format=${format}`);if(!r.ok)throw Error('报告尚未就绪');download(format==='json'?'report.json':'report.md',await r.text(),format==='json'?'application/json':'text/markdown')}else{const r=state.run.report;let text=JSON.stringify(r,null,2);if(format==='markdown')text=`# ArtiCheck — ${r.paper_id}\n\nSource: archived sample replay\n\n| Claim | Verdict | Reason |\n|---|---|---|\n`+r.findings.map(f=>`| ${f.claim_id} | ${f.verdict} | ${f.reason.replaceAll('|','\\|')} |`).join('\n');download(format==='json'?'report.json':'report.md',text,format==='json'?'application/json':'text/markdown')}toast('报告已导出');closeModal()}catch(error){toast(error.message)}}
async function action(name,element){try{switch(name){case 'nav':state.page=element.dataset.page;location.hash=state.page;render();break;case 'new':showNew();break;case 'connection':connection();break;case 'help':modal('从主张到证据',`<div class="stack"><p class="field-hint">1. 新建核查：选择教学任务，或在本地运行时导入 task.json。</p><p class="field-hint">2. 查看六角色流程，点击主张检查实际输出与判定。</p><p class="field-hint">3. 人工复核保留原判定，修正记录在训练交接页归档。</p><p class="field-hint">4. API 契约页提供可下载的 OpenAPI 和 cURL 请求。</p></div>`);break;case 'close-modal':closeModal();break;case 'claim':state.claimId=element.dataset.id;state.selectedStage=null;state.raw=false;render();break;case 'filter':state.filter=element.dataset.value;render();break;case 'stage':state.selectedStage=element.dataset.id;render();break;case 'close-stage':state.selectedStage=null;render();break;case 'raw':state.raw=!state.raw;render();break;case 'rerun':await startRun(currentTask().id,{sandbox:currentTask().trusted_sample?'local':'docker'});break;case 'cancel':if(!active())break;if(state.mode==='runtime'){await request('/api/runs/'+state.run.id+'/cancel',{});state.run=await request('/api/runs/'+state.run.id)}else{clearInterval(demoTimer);state.run.status='cancelled';state.run.stages=Object.fromEntries(stages.map(s=>[s[0],state.run.stages[s[0]]==='completed'?'completed':'cancelled']))}render();toast('已请求停止');break;case 'endpoint':state.endpoint=Number(element.dataset.index);render();break;case 'download-spec':download('articheck-openapi.json',JSON.stringify(spec,null,2));break;case 'copy-curl':{const e=endpoints()[state.endpoint];const cmd=`curl -X ${e.method.toUpperCase()} 'http://127.0.0.1:8787${e.path}'`+(e.method==='post'?` \\\n  -H 'Content-Type: application/json' \\\n  -H 'X-ArtiCheck-Client: workbench' \\\n  -d '${JSON.stringify(e['x-ui-request'])}'`:'');await copy(cmd);break}case 'copy-command':{const c=currentClaims().find(c=>c.id===state.claimId)||currentClaims()[0];await copy((c.probe||currentTask().manifest.probe).join(' '));break}case 'copy-evidence':{const f=state.run.findings.find(f=>f.claim_id===state.claimId);await copy(f?.evidence_ids[0]||'');break}case 'event':modal('原始事件 · #'+(Number(element.dataset.index)+1),`<pre class="contract-code">${esc(JSON.stringify(state.run.events[Number(element.dataset.index)],null,2))}</pre>`,'',true);break;case 'submit-task':await submitTask();break;case 'feedback':showFeedback();break;case 'submit-feedback':await submitFeedback();break;case 'export':showExport();break;case 'export-json':await exportReport('json');break;case 'export-md':await exportReport('markdown');break;case 'export-trace':download('trace.jsonl',state.run.events.map(e=>JSON.stringify(e)).join('\n')+'\n','application/x-ndjson');break;case 'export-feedback':download('feedback.jsonl',state.feedback.map(e=>JSON.stringify(e)).join('\n')+'\n','application/x-ndjson');break}}catch(error){toast(error.message)}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el)action(el.dataset.action,el);else if(event.target.classList.contains('modal-backdrop'))closeModal()});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.key==='Enter'&&event.target.matches('.claim'))action('claim',event.target);if(event.key==='Tab'&&$('.modal')){const focusables=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(navItems.some(n=>n[0]===page)){state.page=page;render()}});
init();
